!function(){var a=document.getElementById("accordion");fetch("https://saint-roman-main.onrender.com/api/public/faqs").then(function(a){return a.json()}).then(function(n){var o=n.faqs||[];0!==o.length?a.innerHTML=o.map(function(a,n){var o=n+1;return'<div class="accordion-item wow fadeInUp">  <h2 class="accordion-header" id="heading'+o+'">    <button class="accordion-button'+(0===n?"":" collapsed")+'" type="button" data-bs-toggle="collapse" data-bs-target="#collapse'+o+'" aria-expanded="'+(0===n?"true":"false")+'" aria-controls="collapse'+o+'">'+a.question+'    </button>  </h2>  <div id="collapse'+o+'" class="accordion-collapse collapse'+(0===n?" show":"")+'" role="region" aria-labelledby="heading'+o+'" data-bs-parent="#accordion">    <div class="accordion-body"><p>'+a.answer+"</p></div>  </div></div>"}).join(""):a.innerHTML="<p>No FAQs available right now.</p>"}).catch(function(n){a.innerHTML="<p>Could not load FAQs ("+n.message+").</p>"})}();